import { createSlice } from "@reduxjs/toolkit";

export const CART_INITIAL_STATE = {
    isCartOpenGb: false,
    cartItemsGb: []
};

export const cartReducerSlice = createSlice({
    name: 'cart',
    initialState: CART_INITIAL_STATE,
    reducers: {
        setIsCartOpenGb(state, action) {
            state.isCartOpenGb = action.payload;
        },
        setCartItemsGb(state, action) {
            state.cartItemsGb = action.payload;
        }
    }
});

export const { setIsCartOpenGb, setCartItemsGb } = cartReducerSlice.actions;
export const cartReducer = cartReducerSlice.reducer;
